pragma solidity >=0.8.0;

contract CryptoHashDynBoundary {
    bytes32 public packedKeccak;
    bytes32 public encodedKeccak;
    bytes32 public packedSha;
    bytes32 public encodedSha;

    event HashDyn(bytes32 packedKeccak, bytes32 encodedKeccak, bytes32 packedSha, bytes32 encodedSha);

    function set(uint8 a, uint16 b, uint64 c, uint256 d, string memory s) public {
        packedKeccak = keccak256(abi.encodePacked(a, b, c, d, s));
        encodedKeccak = keccak256(abi.encode(a, b, c, d, s));
        packedSha = sha256(abi.encodePacked(a, b, c, d, s));
        encodedSha = sha256(abi.encode(a, b, c, d, s));
        emit HashDyn(packedKeccak, encodedKeccak, packedSha, encodedSha);
    }

    function getPackedKeccak() public view returns (bytes32) { return packedKeccak; }
    function getEncodedKeccak() public view returns (bytes32) { return encodedKeccak; }
    function getPackedSha() public view returns (bytes32) { return packedSha; }
    function getEncodedSha() public view returns (bytes32) { return encodedSha; }
}
